$ErrorActionPreference='Stop'
$repo='O:\repos.hobby\ntvdm64';$root="$repo\build\t473-s10\base-inc-wide-r69";$worker="$repo\build\.ninja\msvc-x86-release\worker";$driver="$repo\build\.ninja\msvc-x86-release\wow32\msvc-x86.cmd"
if(Test-Path $root){throw 'Fresh output required'};New-Item -ItemType Directory $root|Out-Null
$targets=@('obj/bios/reset.obj','obj/ccpu/ccpusas4.obj','obj/bios/bios.obj','obj/bios/tape_io.obj','obj/support/get_env.obj','obj/video/vga_vide.obj','obj/host/config.obj','obj/bios/emm_fncs.obj','obj/bios/build_id.obj','obj/disks/diskbios.obj','obj/support/terminat.obj','obj/host/nt_error.obj','obj/host/stubs.obj','obj/host/nt_rflop.obj')
$before=Get-FileHash (@($targets|ForEach-Object{Join-Path $worker $_})+@("$worker/ntvdm.exe"))
function RunOwned($Name,$Image,$Arguments){$p=Start-Process -FilePath $Image -ArgumentList $Arguments -WorkingDirectory $worker -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/$Name.stdout.txt" -RedirectStandardError "$root/$Name.stderr.txt";try{@{pid=$p.Id;started=$p.StartTime.ToUniversalTime().ToString('o');image=$Image;arguments=$Arguments}|ConvertTo-Json|Set-Content "$root/$Name.process.json";if(!$p.WaitForExit(60000)){& taskkill.exe /PID $p.Id /T /F;throw "$Name budget exceeded"};$p.WaitForExit();$code=$p.ExitCode;@{exit=$code}|ConvertTo-Json|Set-Content "$root/$Name.completion.json";if($code){throw "$Name failed: $code"}}finally{$p.Dispose()}}
$ninja=(Get-Command ninja).Source;$args=$targets -join ' ';RunOwned commands $ninja ('-t commands '+$args);RunOwned deps $ninja ('-t deps '+$args)
$commands=@(Get-Content "$root/commands.stdout.txt");if($commands.Count -ne $targets.Count){throw 'Unexpected dependency commands'}
$records=@(foreach($target in $targets){$unit=($target -replace '^obj/','' -replace '\.obj$','' -replace '/','_');$command=@($commands|Where-Object {$_ -match [regex]::Escape('/Fo'+$target)+'\b'});if($command.Count -ne 1 -or $command[0] -notmatch '/DCPU_40_STYLE\b'){throw "Wrong command $target"};$pp=$command[0].Replace('/Fo'+$target,('/P /Fi"'+$root+'/'+$unit+'.i"'));$body='@echo off'+"`r`n"+'call "'+$driver+'" '+$pp+"`r`n"+'exit /b %errorlevel%'+"`r`n";[IO.File]::WriteAllText("$root/$unit.cmd",$body,[Text.Encoding]::ASCII);RunOwned $unit $env:ComSpec ('/d /s /c ""'+$root+'/'+$unit+'.cmd""');@{unit=$unit;target=$target;original_command=$command[0];preprocess_command=$pp;output="$root/$unit.i";sha256=(Get-FileHash "$root/$unit.i").Hash}})
foreach($r in $before){if((Get-FileHash $r.Path).Hash -ne $r.Hash){throw "Cached production input changed: $($r.Path)"}}
$before|Select-Object Path,Hash|ConvertTo-Json|Set-Content "$root/cache-inputs.json";@{result='pass';units=$records;production_changed=$false;guest_changed=$false;scope='Selected original source preprocessing; no ABI or runtime proof'}|ConvertTo-Json -Depth 6|Set-Content "$root/result.json";'PASS fourteen original production contexts; cached inputs unchanged'
